targets.rawSql:
select date_trunc('day', received_hour) as time, dimensions->>'outcome' as metric, count(*) as value
from telemetry_events where name = 'payment' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
group by 1, 2 order by 1

select step, installs, round(100.0 * installs / nullif(max(installs) over (), 0), 1) as "% of welcome"
from (
  select dimensions->>'step' as step, count(*) as installs
  from telemetry_events where name = 'onboarding' and $__timeFilter(received_hour) and platform in (${platform:sqlstring}) group by 1
) steps
order by array_position(array['welcome','app_onboarded','wallet_ready','funded','first_payment'], step)

select date_trunc('day', received_hour) as time, dimensions->>'wallet' as metric, count(*) as value
from telemetry_events where name = 'launch' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
group by 1, 2 order by 1

select dimensions->>'wallet' as wallet, dimensions->>'action' as action, count(*) as times
from telemetry_events where name = 'wallet_changed' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
group by 1, 2 order by 1, 2

select dimensions->>'setting' as setting, count(*) as launches
from telemetry_events where name = 'setting_changed' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
group by 1 order by 2 desc

select date_trunc('day', received_hour) as time, platform || ' ' || app_version as metric, count(*) as value
from telemetry_events where name = 'launch' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
group by 1, 2 order by 1

select received_hour as time, name as metric, count(*) as value
from telemetry_events where $__timeFilter(received_hour) and platform in (${platform:sqlstring})
group by 1, 2 order by 1

select platform, device_model as device, os_major as "os (API level on Android)", count(*) as launches
from telemetry_events where name = 'launch' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
group by 1, 2, 3 order by 4 desc limit 50
